/** The command: `html`, `outline`, and `defs`, each over the document on standard input, with an
 * optional definitions file. */

import { readFileSync } from 'node:fs'
import { BlockError, headings, parse, render, splitLines } from './block.js'
import { DEFINITION, normalizeLabel } from './defs.js'

const USAGE = 'usage: cli.js html|outline|defs [<definitions>]'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const argv = process.argv.slice(2)
const mode = argv[0]
const defsPath = argv[1]
if (!['html', 'outline', 'defs'].includes(mode) || argv.length < 1 || argv.length > 2) fail(USAGE)

const fileDefs = new Map()
if (defsPath !== undefined) {
  let text
  try {
    text = readFileSync(defsPath, 'utf8')
  } catch {
    fail(`cannot read definitions ${defsPath}`)
  }
  const lines = splitLines(text)
  for (let index = 0; index < lines.length; index += 1) {
    const number = index + 1
    const trimmed = lines[index].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const match = DEFINITION.exec(trimmed)
    if (match === null) fail(`${defsPath}: line ${number}: expected [label]: <url>`)
    const label = normalizeLabel(match[1])
    if (fileDefs.has(label)) fail(`${defsPath}: line ${number}: label ${label} is defined twice`)
    fileDefs.set(label, match[2])
  }
}

let parsed
let docDefs
try {
  const result = parse(splitLines(readFileSync(0, 'utf8')), fileDefs)
  parsed = result.blocks
  docDefs = result.definitions
} catch (error) {
  if (!(error instanceof BlockError)) throw error
  fail(`line ${error.line}: ${error.message}`)
}

if (mode === 'html') {
  const definitions = new Map([...fileDefs, ...docDefs])
  process.stdout.write(render(parsed, definitions))
} else if (mode === 'outline') {
  process.stdout.write(headings(parsed).map(one => `${one.level} ${one.text}\n`).join(''))
} else {
  const entries = []
  for (const [label, url] of fileDefs) entries.push({ label, url, source: 'file' })
  for (const [label, url] of docDefs) entries.push({ label, url, source: 'document' })
  entries.sort((a, b) => (a.label < b.label ? -1 : a.label > b.label ? 1 : 0))
  const lines = entries.map(entry => `${entry.label} ${entry.url} ${entry.source}\n`)
  lines.push(`total ${entries.length}\n`)
  process.stdout.write(lines.join(''))
}
"}

